/bin/bash -lc "python3 - <<'PY'
import ast,json,subprocess,hashlib
from pathlib import Path
root=Path('/workspace'); p=json.loads((root/'proposal.json').read_text())
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
def validate(value,schema,path='study'):
 types={'object':dict,'array':list,'string':str,'boolean':bool,'integer':int,'number':(int,float)}
 if 'type' in schema: assert isinstance(value,types[schema['type']]),(path,'type')
 if 'const' in schema: assert value==schema['const'],(path,'const')
 if 'enum' in schema: assert value in schema['enum'],(path,'enum')
 if isinstance(value,dict):
  assert set(schema.get('required',[]))<=set(value),(path,'required')
  if schema.get('additionalProperties') is False: assert set(value)<=set(schema.get('properties',{})),(path,'extra')
  for k,v in value.items():
   if k in schema.get('properties',{}): validate(v,schema['properties'][k],path+'.'+k)
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),(path,'minItems')
  for i,v in enumerate(value): validate(v,schema.get('items',{}),path+f'[{i}]')
 if isinstance(value,str): assert len(value)>=schema.get('minLength',0),(path,'minLength')
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert 1<=len(p['variants'])<=4
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
ancestor=ast.parse((root/'history_g0_r0016_oldest_bound.py').read_text())
oldclass=next(n for n in ancestor.body if isinstance(n,ast.ClassDef))
old={n.name:n for n in oldclass.body if isinstance(n,ast.FunctionDef)}
models=[]
for v in p['variants']:
 assert v['role'] in ('candidate','control')
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 code=(root/v['file']).read_text();compile(code,v['file'],'exec');t=ast.parse(code)
 cfg=next(ast.literal_eval(n.value) for n in t.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets))
 assert cfg==v['config']
 for n in ast.walk(t):
  if isinstance(n,(ast.Import,ast.ImportFrom)):
   modules=[a.name for a in n.names] if isinstance(n,ast.Import) else [n.module]
   assert all(m.split('.')[0] in ('torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib') for m in modules),modules
  if isinstance(n,ast.Name): assert n.id not in ('open','eval','exec','compile','__import__','globals','locals','input','breakpoint')
 cls=next(n for n in t.body if isinstance(n,ast.ClassDef)); models.append(ast.dump(cls,include_attributes=False))
 methods={n.name:n for n in cls.body if isinstance(n,ast.FunctionDef)}
 inherited=[name for name in old if name not in ('__init__','_correction_inputs','_readout','diagnostics')]
 for name in inherited: assert ast.dump(methods[name])==ast.dump(old[name]),name
 assert [ast.dump(n) for n in methods['__init__'].body[:len(old['__init__'].body)]]==[ast.dump(n) for n in old['__init__'].body]
 diag=methods['diagnostics'];d=next(n.value for n in diag.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='result' for x in n.targets))
 keys=[ast.literal_eval(k) for k in d.keys];assert len(keys)==len(set(keys)) and len(keys)<=64
 print(v['file'],'syntax/import/config PASS;',len(inherited),'unchanged inherited methods; exact ancestor constructor prefix;',len(keys),'diagnostic scalars; sha256',hashlib.sha256(code.encode()).hexdigest())
assert len(set(models))==1
assert {a['knowledge_id'] for a in p['knowledge_assessments']}==set(r['context']['latest_knowledge_usage']['retrieved_ids'])
assert all(a['decision'] in ('used','considered','rejected','unresolved') for a in p['knowledge_assessments'])
print('Study schema, evidence IDs, four-arm factorial, source boundaries, identical Model ASTs and knowledge coverage PASS.')
print('Tensor forward/backward, measured parameter count and performance are NOT executed by these checks.')
PY"

